UPDATE lessons SET content = $lsn${"steps": [{"step_type": "intro", "title": "Today's Goal", "instruction": "Let's review 은/는, 이에요/예요 and 을/를 together.", "content": {"explanation": {"title": "Unit 1 review"}, "sentences": [{"korean": "민수는 학생이에요.", "english": "Minsu is a student.", "tts": true, "chunks": [{"display": "민수는", "tokens": [{"text": "민수", "meaning": "Minsu (name)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "학생이에요.", "tokens": [{"text": "학생", "meaning": "student"}, {"text": "이에요", "meaning": "am/is/are (polite)"}]}]}, {"korean": "저는 빵을 먹어요.", "english": "I eat bread.", "tts": true, "chunks": [{"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "빵을", "tokens": [{"text": "빵", "meaning": "bread"}, {"text": "을", "meaning": "object marker"}]}, {"display": "먹어요.", "tokens": [{"text": "먹", "meaning": "eat"}, {"text": "어요", "meaning": "polite ending"}]}]}]}}, {"step_type": "intro", "title": "Conversation #1", "instruction": "Listen to Minsu and Yumi talk about jobs and what they like.", "content": {"explanation": {"title": "Jobs and likes"}, "sentences": [{"korean": "유미: 민수 씨는 무슨 일 하세요?", "english": "Yumi: Minsu, what do you do?", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "민수", "tokens": [{"text": "민수", "meaning": "Minsu (name)"}]}, {"display": "씨는", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}, {"text": "는", "meaning": "topic marker"}]}, {"display": "무슨", "tokens": [{"text": "무슨", "meaning": "what"}]}, {"display": "일", "tokens": [{"text": "일", "meaning": "work/job"}]}, {"display": "하세요?", "tokens": [{"text": "하세요", "meaning": "do (polite)"}]}]}, {"korean": "민수: 저는 학생이에요.", "english": "Minsu: I am a student.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "학생이에요.", "tokens": [{"text": "학생", "meaning": "student"}, {"text": "이에요", "meaning": "am/is/are (polite)"}]}]}, {"korean": "유미: 아, 저는 선생님이에요. 민수 씨는 뭐를 좋아해요?", "english": "Yumi: Ah, I am a teacher. Minsu, what do you like?", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "아,", "tokens": [{"text": "아", "meaning": "Ah"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "선생님이에요.", "tokens": [{"text": "선생님", "meaning": "teacher"}, {"text": "이에요", "meaning": "am/is/are (polite)"}]}, {"display": "민수", "tokens": [{"text": "민수", "meaning": "Minsu (name)"}]}, {"display": "씨는", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}, {"text": "는", "meaning": "topic marker"}]}, {"display": "뭐를", "tokens": [{"text": "뭐", "meaning": "what"}, {"text": "를", "meaning": "object marker"}]}, {"display": "좋아해요?", "tokens": [{"text": "좋아하", "meaning": "like"}, {"text": "어요", "meaning": "polite ending"}]}]}, {"korean": "민수: 저는 빵을 좋아해요.", "english": "Minsu: I like bread.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "빵을", "tokens": [{"text": "빵", "meaning": "bread"}, {"text": "을", "meaning": "object marker"}]}, {"display": "좋아해요.", "tokens": [{"text": "좋아하", "meaning": "like"}, {"text": "어요", "meaning": "polite ending"}]}]}]}}, {"step_type": "intro", "title": "Grammar: Unit 1 Review", "instruction": "Three things you learned in this unit. Each one depends on the last sound of the word.", "content": {"explanation": {"title": "Consonant vs Vowel ending", "patterns": [{"pattern": "은 / 는", "level": "Review", "usage": "It marks the topic. After a consonant use 은, after a vowel use 는."}, {"pattern": "이에요 / 예요", "level": "Review", "usage": "It means 'am/is/are'. After a consonant use 이에요, after a vowel use 예요."}, {"pattern": "을 / 를", "level": "Review", "usage": "It marks the object. After a consonant use 을, after a vowel use 를."}]}, "sentences": [{"korean": "저는 = I (topic)", "english": "저 (ends with vowel ㅓ) + 는", "tts": false, "chunks": [{"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "=", "tokens": []}, {"display": "I", "tokens": []}, {"display": "(topic)", "tokens": []}]}, {"korean": "이름은 = name (topic)", "english": "이름 (ends with consonant ㅁ) + 은", "tts": false, "chunks": [{"display": "이름은", "tokens": [{"text": "이름", "meaning": "name"}, {"text": "은", "meaning": "topic marker"}]}, {"display": "=", "tokens": []}, {"display": "name", "tokens": []}, {"display": "(topic)", "tokens": []}]}, {"korean": "의사예요 = am a doctor", "english": "의사 (ends with vowel ㅏ) + 예요", "tts": false, "chunks": [{"display": "의사예요", "tokens": [{"text": "의사", "meaning": "doctor"}, {"text": "예요", "meaning": "am/is/are (polite)"}]}, {"display": "=", "tokens": []}, {"display": "am", "tokens": []}, {"display": "a", "tokens": []}, {"display": "doctor", "tokens": []}]}, {"korean": "학생이에요 = am a student", "english": "학생 (ends with consonant ㅇ) + 이에요", "tts": false, "chunks": [{"display": "학생이에요", "tokens": [{"text": "학생", "meaning": "student"}, {"text": "이에요", "meaning": "am/is/are (polite)"}]}, {"display": "=", "tokens": []}, {"display": "am", "tokens": []}, {"display": "a", "tokens": []}, {"display": "student", "tokens": []}]}, {"korean": "커피를 = coffee (object)", "english": "커피 (ends with vowel ㅣ) + 를", "tts": false, "chunks": [{"display": "커피를", "tokens": [{"text": "커피", "meaning": "coffee"}, {"text": "를", "meaning": "object marker"}]}, {"display": "=", "tokens": []}, {"display": "coffee", "tokens": []}, {"display": "(object)", "tokens": []}]}, {"korean": "빵을 = bread (object)", "english": "빵 (ends with consonant ㅇ) + 을", "tts": false, "chunks": [{"display": "빵을", "tokens": [{"text": "빵", "meaning": "bread"}, {"text": "을", "meaning": "object marker"}]}, {"display": "=", "tokens": []}, {"display": "bread", "tokens": []}, {"display": "(object)", "tokens": []}]}]}}, {"step_type": "practice", "title": "Pattern Practice", "instruction": "Choose the right answer.", "content": {"exercises": [{"type": "fill_blank", "instruction": "Minsu is a student.", "sentence": "민수 [ ? ] 학생이에요.", "options": ["은", "는"], "answer": "는", "feedback": {"correct": "Correct! 민수 ends in a vowel, so + 는"}}, {"type": "fill_blank", "instruction": "My name is Yumi.", "sentence": "제 이름 [ ? ] 유미예요.", "options": ["은", "는"], "answer": "은", "feedback": {"correct": "Right! 이름 ends in a consonant, so + 은"}}, {"type": "fill_blank", "instruction": "I am a teacher.", "sentence": "저는 선생님 [ ? ].", "options": ["예요", "이에요"], "answer": "이에요", "feedback": {"correct": "Great! 선생님 ends in a consonant, so + 이에요"}}, {"type": "fill_blank", "instruction": "I am a doctor.", "sentence": "저는 의사 [ ? ].", "options": ["이에요", "예요"], "answer": "예요", "feedback": {"correct": "Perfect! 의사 ends in a vowel, so + 예요"}}, {"type": "fill_blank", "instruction": "I eat an apple.", "sentence": "저는 사과 [ ? ] 먹어요.", "options": ["을", "를"], "answer": "를", "feedback": {"correct": "Correct! 사과 ends in a vowel, so + 를"}}, {"type": "fill_blank", "instruction": "Minsu drinks water.", "sentence": "민수는 물 [ ? ] 마셔요.", "options": ["를", "을"], "answer": "을", "feedback": {"correct": "Right! 물 ends in a consonant, so + 을"}}, {"type": "fill_blank", "instruction": "Yumi eats bread.", "sentence": "유미 [ ? ] 빵을 먹어요.", "options": ["는", "를"], "answer": "는", "feedback": {"correct": "Great! 유미 is the topic, so + 는"}}, {"type": "fill_blank", "instruction": "I am an office worker.", "sentence": "저는 회사원 [ ? ].", "options": ["예요", "이에요"], "answer": "이에요", "feedback": {"correct": "Perfect! 회사원 ends in a consonant, so + 이에요"}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"Minsu is a student.\" Split 은/는 and 이에요/예요.", "contentObj": {"sentence": "민수는 학생이에요.", "translation": "Minsu is a student.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["민수는"], "correct_turtle": ["민수", "는"], "turtle_explanation": "'는' marks the topic. After a vowel use 는, after a consonant use 은."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["학생이에요"], "correct_turtle": ["학생", "이에요"], "turtle_explanation": "'이에요' means 'am/is/are'. After a consonant use 이에요, after a vowel use 예요."}], "options": [{"id": "o1", "text": "민수", "mode": "turtle"}, {"id": "o2", "text": "학생예요", "mode": "rabbit"}, {"id": "o3", "text": "민수은", "mode": "rabbit"}, {"id": "o4", "text": "학생", "mode": "turtle"}, {"id": "o5", "text": "예요", "mode": "turtle"}, {"id": "o6", "text": "은", "mode": "turtle"}, {"id": "o7", "text": "민수는", "mode": "rabbit"}, {"id": "o8", "text": "학생이에요", "mode": "rabbit"}, {"id": "o9", "text": "는", "mode": "turtle"}, {"id": "o10", "text": "이에요", "mode": "turtle"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"Yumi is a teacher.\" Split 은/는 and 이에요/예요.", "contentObj": {"sentence": "유미는 선생님이에요.", "translation": "Yumi is a teacher.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["유미는"], "correct_turtle": ["유미", "는"], "turtle_explanation": "'는' marks the topic. After a vowel use 는, after a consonant use 은."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["선생님이에요"], "correct_turtle": ["선생님", "이에요"], "turtle_explanation": "'이에요' means 'am/is/are'. After a consonant use 이에요, after a vowel use 예요."}], "options": [{"id": "o1", "text": "선생님", "mode": "turtle"}, {"id": "o2", "text": "선생님이에요", "mode": "rabbit"}, {"id": "o3", "text": "예요", "mode": "turtle"}, {"id": "o4", "text": "는", "mode": "turtle"}, {"id": "o5", "text": "유미", "mode": "turtle"}, {"id": "o6", "text": "은", "mode": "turtle"}, {"id": "o7", "text": "유미은", "mode": "rabbit"}, {"id": "o8", "text": "유미는", "mode": "rabbit"}, {"id": "o9", "text": "이에요", "mode": "turtle"}, {"id": "o10", "text": "선생님예요", "mode": "rabbit"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #3", "instruction": "Build the sentence: \"I eat bread.\" Split 은/는 and 을/를.", "contentObj": {"sentence": "저는 빵을 먹어요.", "translation": "I eat bread.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저", "는"], "turtle_explanation": "'는' marks the topic. After a vowel use 는, after a consonant use 은."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["빵을"], "correct_turtle": ["빵", "을"], "turtle_explanation": "'을' marks the object. After a vowel use 를, after a consonant use 을."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["먹어요"], "correct_turtle": ["먹어요"], "turtle_explanation": "Keep '먹어요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "빵을", "mode": "rabbit"}, {"id": "o2", "text": "먹어요", "mode": "turtle"}, {"id": "o3", "text": "는", "mode": "turtle"}, {"id": "o4", "text": "저", "mode": "turtle"}, {"id": "o5", "text": "빵", "mode": "turtle"}, {"id": "o6", "text": "은", "mode": "turtle"}, {"id": "o7", "text": "저는", "mode": "rabbit"}, {"id": "o8", "text": "저은", "mode": "rabbit"}, {"id": "o9", "text": "먹어요", "mode": "rabbit"}, {"id": "o10", "text": "를", "mode": "turtle"}, {"id": "o11", "text": "빵를", "mode": "rabbit"}, {"id": "o12", "text": "을", "mode": "turtle"}]}}, {"step_type": "completion", "title": "Unit 1 Review Complete!", "instruction": "Great! You can now use everything from Unit 1 together.", "content": {"text": "You reviewed 은/는, 이에요/예요 and 을/를.\nConsonant ending → 은, 이에요, 을. Vowel ending → 는, 예요, 를.", "highlights": ["은/는", "이에요/예요", "을/를"]}}]}$lsn$::jsonb
