: "polite ending"}]}, {"display": "=", "tokens": []}, {"display": "don't", "tokens": []}, {"display": "have", "tokens": []}, {"display": "coffee", "tokens": []}]}, {"korean": "학교에 가요 = go to school", "english": "에: where you go", "tts": false, "chunks": [{"display": "학교에", "tokens": [{"text": "학교", "meaning": "school"}, {"text": "에", "meaning": "place marker"}]}, {"display": "가요", "tokens": [{"text": "가", "meaning": "go"}, {"text": "어요", "meaning": "polite ending"}]}, {"display": "=", "tokens": []}, {"display": "go", "tokens": []}, {"display": "to", "tokens": []}, {"display": "school", "tokens": []}]}, {"korean": "학교에서 공부해요 = study at school", "english": "에서: where you do something", "tts": false, "chunks": [{"display": "학교에서", "tokens": [{"text": "학교", "meaning": "school"}, {"text": "에서", "meaning": "action place marker"}]}, {"display": "공부해요", "tokens": [{"text": "공부", "meaning": "study"}, {"text": "하", "meaning": "do"}, {"text": "어요", "meaning": "polite ending"}]}, {"display": "=", "tokens": []}, {"display": "study", "tokens": []}, {"display": "at", "tokens": []}, {"display": "school", "tokens": []}]}, {"korean": "커피를 안 마셔요 = don't drink coffee", "english": "안 goes right before the verb.", "tts": false, "chunks": [{"display": "커피를", "tokens": [{"text": "커피", "meaning": "coffee"}, {"text": "를", "meaning": "object marker"}]}, {"display": "안", "tokens": [{"text": "안", "meaning": "not"}]}, {"display": "마셔요", "tokens": [{"text": "마시", "meaning": "drink"}, {"text": "어요", "meaning": "polite ending"}]}, {"display": "=", "tokens": []}, {"display": "don't", "tokens": []}, {"display": "drink", "tokens": []}, {"display": "coffee", "tokens": []}]}]}}, {"step_type": "practice", "title": "Pattern Practice", "instruction": "Choose the right answer.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I don't have money.", "sentence": "저는 돈 [ ? ] 없어요.", "options": ["이", "가"], "answer": "이", "feedback": {"correct": "Correct! 돈 ends in a consonant, so + 이"}}, {"type": "fill_blank", "instruction": "There is milk.", "sentence": "우유 [ ? ] 있어요.", "options": ["에", "가"], "answer": "가", "feedback": {"correct": "Right! Milk is not a place. It is the thing that exists, so + 가"}}, {"type": "fill_blank", "instruction": "I go to the library.", "sentence": "저는 도서관 [ ? ] 가요.", "options": ["에서", "에"], "answer": "에", "feedback": {"correct": "Great! 도서관 is where you go, so + 에"}}, {"type": "fill_blank", "instruction": "Minsu reads a book at the library.", "sentence": "민수는 도서관 [ ? ] 책을 읽어요.", "options": ["에", "에서"], "answer": "에서", "feedback": {"correct": "Perfect! Minsu does something at 도서관, so + 에서"}}, {"type": "fill_blank", "instruction": "Yumi is at home now.", "sentence": "유미는 지금 집 [ ? ] 있어요.", "options": ["에서", "에"], "answer": "에", "feedback": {"correct": "Correct! 집 is where Yumi is, so + 에"}}, {"type": "fill_blank", "instruction": "I don't drink milk.", "sentence": "저는 우유를 [ ? ].", "options": ["안 마셔요", "마셔요 안"], "answer": "안 마셔요", "feedback": {"correct": "Right! 안 goes right before the verb."}}, {"type": "fill_blank", "instruction": "Minsu eats at a restaurant.", "sentence": "민수는 식당 [ ? ] 밥을 먹어요.", "options": ["에", "에서"], "answer": "에서", "feedback": {"correct": "Great! Minsu does something at 식당, so + 에서"}}, {"type": "fill_blank", "instruction": "Yumi doesn't go to school today.", "sentence": "유미는 오늘 학교에 [ ? ].", "options": ["가요 안", "안 가요"], "answer": "안 가요", "feedback": {"correct": "Perfect! 안 goes right before the verb."}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"Minsu has a friend at school.\" Split 에 and 이/가.", "contentObj": {"sentence": "민수는 학교에 친구가 있어요.", "translation": "Minsu has a friend at school.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["민수는"], "correct_turtle": ["민수는"], "turtle_explanation": "Keep '민수는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["학교에"], "correct_turtle": ["학교", "에"], "turtle_explanation": "'에' marks a place: where you go or where something is. It is the same after a consonant or a vowel."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["친구가"], "correct_turtle": ["친구", "가"], "turtle_explanation": "'가' marks the subject. After a vowel use 가, after a consonant use 이."}, {"id": "e4", "isTarget": true, "correct_rabbit": ["있어요"], "correct_turtle": ["있어요"], "turtle_explanation": "Keep '있어요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "이", "mode": "turtle"}, {"id": "o2", "text": "민수는", "mode": "rabbit"}, {"id": "o3", "text": "민수는", "mode": "turtle"}, {"id": "o4", "text": "학교에", "mode": "rabbit"}, {"id": "o5", "text": "학교가", "mode": "rabbit"}, {"id": "o6", "text": "가", "mode": "turtle"}, {"id": "o7", "text": "에", "mode": "turtle"}, {"id": "o8", "text": "에서", "mode": "turtle"}, {"id": "o9", "text": "학교", "mode": "turtle"}, {"id": "o10", "text": "있어요", "mode": "rabbit"}, {"id": "o11", "text": "친구가", "mode": "rabbit"}, {"id": "o12", "text": "있어요", "mode": "turtle"}, {"id": "o13", "text": "친구", "mode": "turtle"}, {"id": "o14", "text": "친구이", "mode": "rabbit"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"Yumi doesn't go to the office.\" Split 에. 안 stays whole.", "contentObj": {"sentence": "유미는 회사에 안 가요.", "translation": "Yumi doesn't go to the office.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["유미는"], "correct_turtle": ["유미는"], "turtle_explanation": "Keep '유미는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["회사에"], "correct_turtle": ["회사", "에"], "turtle_explanation": "'에' marks a place: where you go or where something is. It is the same after a consonant or a vowel."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["안"], "correct_turtle": ["안"], "turtle_explanation": "'안' means 'not'. It goes right before the verb."}, {"id": "e4", "isTarget": true, "correct